SELECT COUNT(CDSCode)
FROM frpm
WHERE CharterSchool (Y/N) = 0 AND County Name = 'Los Angeles' AND Percent (%) Eligible Free (K-12) < 0.18;

SELECT T1.SchoolName, T2.Percent (%) Eligible FRPM (Ages 5-17) 
FROM schools AS T1 INNER JOIN frpm AS T2 ON T1.CDSCode = T2.CDSCode 
WHERE T1.County = 'Los Angeles' AND T2.LowGrade = 'K' AND T2.HighGrade = '9';

SELECT T1.name, T2.translation, T2.language 
FROM cards AS T1 INNER JOIN set_translations AS T2 ON T1.setCode = T2.setCode 
WHERE T1.setCode = '10E' AND T1.convertedManaCost = 5;

SELECT COUNT(DISTINCT u.Id) 
FROM badges b JOIN users u ON b.UserId = u.Id 
WHERE b.Name = 'Supporter' AND u.Age BETWEEN 19 AND 65;

SELECT COUNT(DISTINCT T1.UserId) 
FROM badges AS T1 INNER JOIN comments AS T2 ON T1.Id = T2.Score 
WHERE T1.Name = 'Commentator' AND STRFTIME('%Y', T1.Date) = '2014';

SELECT u.DisplayName, u.WebsiteUrl 
FROM posts p JOIN users u ON p.OwnerUserId = u.Id 
WHERE p.FavoriteCount > 150;

SELECT u.DisplayName, u.WebsiteUrl 
FROM users u JOIN votes v ON u.Id = v.UserId 
WHERE v.VoteTypeId = 8 ORDER BY v.BountyAmount DESC LIMIT 1;

SELECT T1.CreationDate 
FROM posts AS T1 INNER JOIN users AS T2 ON T1.OwnerUserId = T2.Id 
WHERE (T2.Age = ( SELECT MIN(Age) FROM users )) AND (T1.CreationDate = ( SELECT MIN(CreationDate) FROM posts ));
